{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "A structurally related triterpenoid saponin (A-VI) reached 248.7 ng/g in rat brain after systemic dosing and was classified as BBB-permeable, supporting meaningful CNS access for glycosylated terpenoid natural products.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A glucose-bearing compound was detected in rat brain at 3.1 nmol/g and its transport was attributed to GLUT1-mediated uptake; the query's single glucose moiety provides a plausible active uptake mechanism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Ciwujianoside C3, a saponin glycoside, was detected in mouse cerebral cortex after oral administration, demonstrating that glycosylated terpenoids can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Epimedin B, a large multi-glycosylated flavonol, was essentially unable to cross the BBB, illustrating that extensive glycosylation/polarity can prevent CNS access; this is less transferable because the query has only one sugar and a lipophilic aglycone.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic diterpenoid-like aglycone bearing a single glucose and an aldehyde. Multiple glycosylated terpenoid natural products with similar scaffolds are experimentally BBB-permeable, and glucose moieties can engage GLUT1-mediated uptake. The few impermeable examples are much more polar/larger glycosides or aminoglycosides, so the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma measurement for the exact query molecule.",
    "Morgan similarities to evidence molecules are low, limiting quantitative transferability.",
    "Extent of CNS exposure and possible efflux liability are not quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

